const euro = (value: number, language: Language, digits = 2) => new Intl.NumberFormat(language === 'en' ? 'en-IE' : 'zh-CN', { style: 'currency', currency: 'EUR', minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value);
const kw = (value: number) => `${value.toFixed(2)} kW`;
function SectionHeading({ title, aside }: { title: string; aside?: ReactNode }) { return <div className="home-section-heading"><h2>{title}</h2>{aside}</div>; }
function Chip({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'amber' }) { return <span className={`home-chip ${tone}`}>{children}</span>; }
function Notice({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'amber' }) { return <div className={`home-notice ${tone}`}><Icon name="info" size={17}/><div>{children}</div></div>; }
function newerSettlement(current?: Settlement | null, incoming?: Settlement | null): Settlement | null {
  if (!current) return incoming ?? null;
  if (!incoming) return current;
  const captured = (record:Settlement) => typeof record.captured_at === 'string' && Number.isFinite(Date.parse(record.captured_at)) ? Date.parse(record.captured_at) : Number.NEGATIVE_INFINITY;
  const before=captured(current); const after=captured(incoming);
  if (after > before) return incoming;
  if (after < before) return current;
  return current.status !== 'complete' && incoming.status === 'complete' ? incoming : current;
}
function actionText(station: Station, t: Translate) {
  if (station.action.control_semantics === 'self_consumption') return t('Use household self-use mode', '使用家庭自用模式');
  if (station.action.control_semantics === 'grid_export_target') return t('A grid export target is proposed', '建议调整并网外送目标');
  return station.action.kind === 'charge' ? t('A plan to store energy for later', '为接下来的用电安排储能') : station.action.kind === 'discharge' ? t('A plan to put stored energy to work', '让存下的电在需要时发挥作用') : t('Recommendation meaning needs checking', '建议含义待核验');
}
function readableSummary(station: Station, decision: Decision | undefined, explanation: Explanation | undefined, ctx: Context) {
  const original = explanation?.summary || station.reason_summary;
  if (ctx.language === 'zh' || (original && !/[\u3400-\u9fff]/.test(original))) return original || ctx.t('No recorded reason is available yet.', '暂时没有记录中的原因。');
  const prices = decision?.snapshot.import_eur_kwh;
  if (prices?.length && prices.every(Number.isFinite)) return `In this scenario, buying starts at ${euro(prices[0], 'en', 3)}/kWh and the highest forecast rate is ${euro(Math.max(...prices), 'en', 3)}/kWh. Your battery holds ${station.soc_percent.toFixed(0)}%.`;
  return `Your battery holds ${station.soc_percent.toFixed(0)}% and home demand is ${kw(station.load_kw)} in this snapshot. The original reason is available in the evidence view.`;
}
function SourceNote({ station, settlement, t }: { station: Station; settlement?: Settlement | null; t: Translate }) {
  return <><Chip tone={artificial(station) ? 'amber' : 'neutral'}>{artificial(station) ? t('Demo scenario', '人工演示情景') : t('Imported home snapshot', '导入的家庭快照')}</Chip>{settlement?.source_kind === 'simulator_mock' && <Chip tone="amber">{t('Mock race data · not real household metering', '模拟赛数据 · 非真实家庭计量')}</Chip>}</>;
}
function LastSubmission({ station, ctx }: { station: Station; ctx: Context }) {
  const submission = station.last_submission;
  if (!submission) return null;
  return <div className="home-submission-history"><strong>{ctx.t('Last submitted instruction · history', '最近下发记录 · 历史')}</strong><p>{formatTime(submission.device_time,ctx.zone,ctx.language,true)} · {kw(submission.action.power_kw)}</p><p className="home-footnote">{ctx.t('This belongs to an earlier decision. It does not describe the current control mode.', '这属于先前决策，不能代表设备当前控制模式。')}</p><button className="home-text-button" onClick={()=>{window.location.hash=`/decisions/${encodeURIComponent(submission.decision_key)}`;}}>{ctx.t('Review submission and readback', '查看下发与回读记录')}<Icon name="arrow" size={16}/></button></div>;
}
